const fs = require('fs');
const path = require('path');

const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

function slug(value) {
  const s = String(value || '').toLowerCase().replace(/[^a-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
  if (!s) throw new Error('product_id is required');
  return s;
}
function requiredEnv(name) {
  const value = $env[name];
  if (!value) throw new Error(`${name} environment variable is required`);
  return value;
}
function toBool(value, defaultValue = false) {
  if (value === true || value === false) return value;
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (normalized === 'true') return true;
    if (normalized === 'false') return false;
  }
  return defaultValue;
}
function normalizeLocalRoot(value) {
  return String(value).replace(/\\/g, '/').replace(/\/+$/, '');
}
function repoPathUrl(repoPath) {
  return encodeURIComponent(repoPath).replace(/%2F/g, '/');
}
function cdnUrl(owner, repo, branch, repoPath) {
  const encodedPath = repoPath.split('/').map(part => encodeURIComponent(part)).join('/');
  return `https://cdn.jsdelivr.net/gh/${owner}/${repo}@${branch}/${encodedPath}`;
}
function readFileBase64(filePath) {
  const stat = fs.statSync(filePath);
  const maxBytes = 95 * 1024 * 1024;
  if (stat.size > maxBytes) {
    throw new Error(`File is too large for GitHub Contents API (${stat.size} bytes): ${filePath}`);
  }
  return fs.readFileSync(filePath).toString('base64');
}
function summarizeError(error) {
  return error?.message || String(error);
}
async function githubRequest(method, url, token, body, label) {
  const options = {
    method,
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'n8n-local-video-automation'
    },
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 120000
  };
  if (body !== undefined) {
    options.headers['Content-Type'] = 'application/json';
    options.body = body;
  }

  let lastError;
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const response = await helpers.httpRequest(options);
      const statusCode = Number(response?.statusCode || 0);
      if (![408, 409, 429, 500, 502, 503, 504].includes(statusCode)) {
        return response;
      }
      lastError = new Error(`GitHub ${method} retryable HTTP ${statusCode} for ${label}: ${JSON.stringify(response.body)}`);
    } catch (error) {
      lastError = error;
    }

    if (attempt < 5) {
      await sleep(1000 * attempt * attempt);
    }
  }
  throw new Error(`GitHub ${method} failed after retries for ${label}: ${summarizeError(lastError)}`);
}

async function githubGet(owner, repo, branch, repoPath, token) {
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${repoPathUrl(repoPath)}?ref=${encodeURIComponent(branch)}`;
  const response = await githubRequest('GET', url, token, undefined, repoPath);
  if (response.statusCode === 404) return null;
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`GitHub GET failed ${response.statusCode} for ${repoPath}: ${JSON.stringify(response.body)}`);
  }
  return response.body;
}

async function githubPut(owner, repo, branch, repoPath, contentBase64, message, token, skipIfUnchanged = false) {
  const existing = await githubGet(owner, repo, branch, repoPath, token);
  if (skipIfUnchanged && existing?.content) {
    const currentContent = String(existing.content).replace(/\s/g, '');
    const nextContent = String(contentBase64).replace(/\s/g, '');
    if (currentContent === nextContent) {
      return { unchanged: true, sha: existing.sha };
    }
  }
  const body = { message, content: contentBase64, branch };
  if (existing?.sha) body.sha = existing.sha;
  const url = `https://api.github.com/repos/${owner}/${repo}/contents/${repoPathUrl(repoPath)}`;
  const response = await githubRequest('PUT', url, token, body, repoPath);
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`GitHub PUT failed ${response.statusCode} for ${repoPath}: ${JSON.stringify(response.body)}`);
  }
  return response.body;
}

const input = $json.body ?? $json;
const productId = slug(input.product_id);
const owner = input.owner || $env.GITHUB_OWNER || 'fye2552';
const repo = input.repo || $env.GITHUB_REPO || 'video_automation_repo';
const branch = input.branch || $env.GITHUB_BRANCH || 'main';
const token = requiredEnv('GITHUB_TOKEN');
const localProductsRoot = normalizeLocalRoot($env.N8N_LOCAL_PRODUCTS_DIR || 'E:/n8n-video-gemini/local_products');
const projectRoot = normalizeLocalRoot(path.dirname(localProductsRoot));
const localDir = `${localProductsRoot}/${productId}`;
const profilePath = path.join(localDir, 'product_profile.yaml');
if (!fs.existsSync(profilePath)) throw new Error(`product_profile.yaml is required: ${profilePath}`);
const planPath = path.join(localDir, 'plan_batch_001.md');
const imageSourceDirs = [
