  path.join(localDir, 'reference_images'),
  path.join(localDir, 'skill_a', 'images'),
  path.join(localDir, 'skill_a', 'reference_images'),
  // Compatibility fallback: some product packs keep source images directly in the product root.
  localDir
];
const warnings = [];
const uploads = [];
let imageUploadWarning = '';
const activeSkill = input.active_skill || 'skill_c';

if (activeSkill === 'skill_e') {
  const skillEPath = normalizeLocalRoot($env.N8N_SKILL_E_PATH || path.join(projectRoot, 'SKILL-E.md'));
  if (!fs.existsSync(skillEPath) || !fs.statSync(skillEPath).isFile()) {
    throw new Error(`Skill E source file is required: ${skillEPath}`);
  }
  uploads.push({
    local: skillEPath,
    repoPath: 'skills/skill_e.md',
    skipIfUnchanged: true,
    isSkill: true
  });
}

uploads.push({ local: profilePath, repoPath: `products/${productId}/skill_a/product_profile.yaml` });
if (fs.existsSync(planPath)) {
  uploads.push({ local: planPath, repoPath: `products/${productId}/skill_a/plan_batch_001.md` });
} else {
  uploads.push({ contentBase64: Buffer.from('', 'utf8').toString('base64'), repoPath: `products/${productId}/skill_a/plan_batch_001.md` });
  warnings.push(`plan_batch_001.md not found for ${productId}; uploaded empty optional file`);
}
const discoveredImages = [];
const seenImageNames = new Set();
for (const sourceDir of imageSourceDirs) {
  if (!fs.existsSync(sourceDir) || !fs.statSync(sourceDir).isDirectory()) continue;
  const imageNames = fs.readdirSync(sourceDir)
    .filter(name => /\.(png|jpe?g|webp)$/i.test(name))
    .sort((a, b) => a.localeCompare(b));
  for (const name of imageNames) {
    const key = name.toLowerCase();
    if (seenImageNames.has(key)) continue;
    seenImageNames.add(key);
    discoveredImages.push({ local: path.join(sourceDir, name), name, sourceDir });
  }
}
if (!discoveredImages.length) {
  imageUploadWarning = 'No local images found under images/reference_images paths';
  warnings.push(imageUploadWarning);
} else {
  for (const image of discoveredImages) {
    uploads.push({
      local: image.local,
      repoPath: `products/${productId}/images/${image.name}`,
      isImage: true
    });
  }
  const standardNames = ['product_white_bg.png', 'product_detail_side.png', 'product_function.png'];
  const missingStandardNames = standardNames.filter(name => !seenImageNames.has(name));
  if (missingStandardNames.length) {
    warnings.push(`Standard image filenames not found: ${missingStandardNames.join(', ')}; original image filenames were uploaded without renaming`);
  }
}
uploads.push({ contentBase64: Buffer.from('', 'utf8').toString('base64'), repoPath: `history/products/${productId}/index.jsonl`, createOnly: true });

const uploaded = [];
const uploadedImages = [];
for (const upload of uploads) {
  if (upload.createOnly) {
    const existing = await githubGet(owner, repo, branch, upload.repoPath, token);
    if (existing) {
      uploaded.push({ path: upload.repoPath, skipped: true });
      continue;
    }
  }
  const contentBase64 = upload.contentBase64 !== undefined ? upload.contentBase64 : readFileBase64(upload.local);
  const putResult = await githubPut(
    owner,
    repo,
    branch,
    upload.repoPath,
    contentBase64,
    `Upload ${upload.repoPath}`,
    token,
    upload.skipIfUnchanged === true
  );
  const bytes = upload.local ? fs.statSync(upload.local).size : 0;
  uploaded.push({ path: upload.repoPath, bytes, unchanged: putResult?.unchanged === true });
  if (upload.isImage) {
    uploadedImages.push({
      local_path: normalizeLocalRoot(upload.local),
      github_path: upload.repoPath,
      cdn_url: cdnUrl(owner, repo, branch, upload.repoPath)
    });
