}];

const input = $json.body ?? $json;
if (!$env.GITHUB_TOKEN) {
  throw new Error('GITHUB_TOKEN environment variable is required for GitHub reads. Configure it in n8n environment or credentials.');
}

function cleanGithubUrl(value) {
  let url = String(value || '').trim();
  const markdownMatch = url.match(/\((https?:\/\/github\.com\/[^)]+)\)/i);
  if (markdownMatch) url = markdownMatch[1];
  url = url.replace(/^<|>$/g, '').trim();
  if (url.startsWith('//github.com/')) url = 'https:' + url;
  if (/^github\.com\//i.test(url)) url = 'https://' + url;
  url = url.replace(/^https:\/github\.com\//i, 'https://github.com/');
  url = url.replace(/^http:\/github\.com\//i, 'http://github.com/');
  try { return decodeURI(url); } catch { return url; }
}

function parseGithubProductUrl(value) {
  const cleaned = cleanGithubUrl(value);
  if (!cleaned) return null;

  let owner;
  let repo;
  let branch;
  let productTail;

  const treeMatch = cleaned.match(/(?:https?:)?\/\/github\.com\/([^\/\s]+)\/([^\/\s]+)\/tree\/(.+)$/i)
    || cleaned.match(/github\.com\/([^\/\s]+)\/([^\/\s]+)\/tree\/(.+)$/i);
  if (treeMatch) {
    owner = treeMatch[1];
    repo = treeMatch[2];
    const rest = treeMatch[3].replace(/^\/+|\/+$/g, '');
    const marker = '/products/';
    const markerIndex = rest.indexOf(marker);
    if (markerIndex < 1) {
      throw new Error(`github_url must include /tree/{branch}/products/{product_id}. Received: ${cleaned}`);
    }
    branch = rest.slice(0, markerIndex);
    productTail = rest.slice(markerIndex + marker.length);
  } else {
    const titleMatch = cleaned.match(/([^\/\s]+)\/products\/([^\s]+)(?:\s+at\s+([^\s]+))?.*?[路\-]\s*([^\/\s]+)\/([^\/\s]+)/i);
    if (titleMatch) {
      repo = titleMatch[1];
      productTail = titleMatch[2];
      branch = titleMatch[3] || 'main';
      owner = titleMatch[4];
      repo = titleMatch[5] || repo;
    } else {
      const shortMatch = cleaned.match(/([^\/\s]+)\/([^\/\s]+)\/products\/([^\s]+)/i);
      if (shortMatch) {
        owner = shortMatch[1];
        repo = shortMatch[2];
        branch = 'main';
        productTail = shortMatch[3];
      }
    }
  }

  if (!owner || !repo || !branch || !productTail) {
    throw new Error(`github_url must look like https://github.com/{owner}/{repo}/tree/{branch}/products/{product_id}. Received: ${cleaned}`);
  }

  productTail = productTail.replace(/^\/+|\/+$/g, '');
  if (!productTail) {
    throw new Error(`github_url must include product_id. Received: ${cleaned}`);
  }

  return {
    github_url: `https://github.com/${owner}/${repo}/tree/${branch}/products/${productTail}`,
    owner,
    repo,
    branch,
    product_folder: `products/${productTail}`
  };
}
const parsedFromUrl = input.github_url ? parseGithubProductUrl(input.github_url) : null;
const owner = parsedFromUrl?.owner || input.owner;
const repo = parsedFromUrl?.repo || input.repo;
const branch = parsedFromUrl?.branch || input.branch || 'main';
const productFolder = parsedFromUrl?.product_folder || input.product_folder;
for (const [key, value] of Object.entries({ owner, repo, product_folder: productFolder })) {
  if (!value) throw new Error(`Missing required input: ${key}. Provide github_url or legacy owner/repo/product_folder.`);
}

const activeSkill = input.active_skill || 'skill_c';
const skillPathByName = {
  skill_b: 'skills/skill_b.md',
  skill_c: 'skills/skill_c.md',
  skill_e: 'skills/skill_e.md',
  new_skill: 'skills/new_skill.md'
};
if (!['skill_b', 'skill_c', 'skill_e', 'new_skill', 'custom'].includes(activeSkill)) {
  throw new Error(`Unsupported active_skill: ${activeSkill}. Use skill_b, skill_c, skill_e, new_skill, or custom.`);
}
if (activeSkill === 'custom' && !input.custom_skill_path) {
  throw new Error('custom_skill_path is required when active_skill is custom');
