const https = require('https');
const { URL } = require('url');

const apiKey = String($env.MOYIN_API_KEY || '').trim();
if (!apiKey) throw new Error('MOYIN_API_KEY environment variable is required for Moyin Create Video.');

function normalizeBaseUrl(value) {
  return String(value || '').trim().replace(/\/+$/, '');
}

function normalizePath(value) {
  const path = String(value || '').trim();
  if (!path) return '';
  return '/' + path.replace(/^\/+/, '');
}

function buildMoyinCreateUrl(baseUrl, createPath) {
  const base = normalizeBaseUrl(baseUrl);
  let path = normalizePath(createPath);

  if (!base) throw new Error('MOYIN_API_BASE_URL / moyin_base_url is required.');
  if (!path) throw new Error('Moyin create.path / moyin_create_path is required.');

  // Avoid duplicate /v1 while preserving a base path such as /api/v1.
  if (/\/v1$/i.test(base) && /^\/v1\//i.test(path)) {
    path = path.replace(/^\/v1/i, '');
  }

  return base + path;
}

function stringify(value) {
  if (typeof value === 'string') return value;
  try { return JSON.stringify(value); } catch (error) { return String(value); }
}

function postJsonNative(urlString, apiKey, bodyObject, timeoutMs = 180000) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const body = JSON.stringify(bodyObject);
    const req = https.request({
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body)
      },
      timeout: timeoutMs
    }, (res) => {
      let raw = '';
      res.on('data', chunk => { raw += chunk.toString(); });
      res.on('end', () => {
        let parsed = raw;
        try { parsed = JSON.parse(raw); } catch (error) {}
        resolve({
          statusCode: Number(res.statusCode || 0),
          headers: res.headers,
          body: parsed,
          raw
        });
      });
    });

    req.on('timeout', () => {
      req.destroy(new Error('Moyin Create Video request timeout'));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

