const token = String($env.GITHUB_TOKEN || '').trim();
if (!token) throw new Error('GITHUB_TOKEN environment variable is required for GitHub history writes.');

const maxRetries = 3;

function encodePath(path) {
  return String(path || '').split('/').map(part => encodeURIComponent(part)).join('/');
}

function decodeBase64(value) {
  return Buffer.from(String(value || ''), 'base64').toString('utf8');
}

function encodeBase64(value) {
  return Buffer.from(String(value || ''), 'utf8').toString('base64');
}

function extractAppendLine(recordContent) {
  const lines = String(recordContent || '').split(/\r?\n/).filter(Boolean);
  return lines.length ? lines[lines.length - 1] : '';
}

function extractScriptIdFromJsonLine(line) {
  try {
    return JSON.parse(line).script_id || '';
  } catch (error) {
    return '';
  }
}

function isShaConflict(statusCode, body) {
  const text = typeof body === 'string' ? body : JSON.stringify(body || {});
  return statusCode === 409 || statusCode === 422 || /sha|expected|is at|conflict/i.test(text);
}

async function githubRequest(method, url, body, ignoreHttpStatusErrors = true) {
  return await this.helpers.httpRequest({
    method,
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github+json',
      'X-GitHub-Api-Version': '2022-11-28',
      'User-Agent': 'n8n-video-history-writer'
    },
    body,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors,
    timeout: 120000
  });
}

async function getCurrentFile(ctx, historyPath) {
  const url = `https://api.github.com/repos/${ctx.owner}/${ctx.repo}/contents/${encodePath(historyPath)}?ref=${encodeURIComponent(ctx.branch)}`;
  const response = await githubRequest.call(this, 'GET', url, undefined, true);
  const statusCode = Number(response.statusCode || 0);

  if (statusCode === 404) {
    return { exists: false, sha: null, content: '' };
  }

  if (statusCode < 200 || statusCode >= 300) {
    const bodyText = typeof response.body === 'string' ? response.body : JSON.stringify(response.body || {});
    throw new Error(`GitHub GET history file failed HTTP ${statusCode}: ${bodyText}`);
  }

  const body = response.body || {};
  const content = body.content ? decodeBase64(String(body.content).replace(/\s/g, '')) : '';
  return { exists: true, sha: body.sha || null, content };
}

async function putFile(ctx, historyPath, content, message, sha) {
  const url = `https://api.github.com/repos/${ctx.owner}/${ctx.repo}/contents/${encodePath(historyPath)}`;
  const body = {
    message,
    content: encodeBase64(content),
    branch: ctx.branch
  };
  if (sha) body.sha = sha;

  return await githubRequest.call(this, 'PUT', url, body, true);
}

function mergeIndexContent(currentContent, appendLine) {
  const currentLines = String(currentContent || '').split(/\r?\n/).filter(Boolean);
  const appendScriptId = extractScriptIdFromJsonLine(appendLine);

  if (appendScriptId) {
    const alreadyExists = currentLines.some(line => extractScriptIdFromJsonLine(line) === appendScriptId);
    if (alreadyExists) return currentLines.join('\n') + (currentLines.length ? '\n' : '');
  }

  if (appendLine) currentLines.push(appendLine);
  return currentLines.join('\n') + (currentLines.length ? '\n' : '');
}

const outputs = [];

for (const item of items) {
  const ctx = item.json;
  const historyPath = ctx.history_path;
  if (!historyPath) throw new Error('history_path is required');

  const originalContent = decodeBase64(ctx.history_content_base64);
  const isIndex = /\/index\.jsonl$/.test(historyPath);
  const appendLine = isIndex ? extractAppendLine(originalContent) : '';

  let lastResponse = null;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const current = await getCurrentFile.call(this, ctx, historyPath);
    const contentToWrite = isIndex
      ? mergeIndexContent(current.content, appendLine)
      : originalContent;

    const response = await putFile.call(this, ctx, historyPath, contentToWrite, ctx.history_message, current.sha);
    lastResponse = response;
    const statusCode = Number(response.statusCode || 0);

    if (statusCode >= 200 && statusCode < 300) {
      outputs.push({
        json: {
          ...ctx,
          github_history_path: historyPath,
          github_history_status: statusCode,
          github_history_sha: response.body?.content?.sha || null,
          github_history_attempts: attempt
        }
      });
      lastResponse = null;
      break;
    }

    if (!isShaConflict(statusCode, response.body) || attempt >= maxRetries) {
      const bodyText = typeof response.body === 'string' ? response.body : JSON.stringify(response.body || {});
      throw new Error(`GitHub PUT history file failed HTTP ${statusCode}: ${bodyText}`);
    }
  }

  if (lastResponse) {
    const bodyText = typeof lastResponse.body === 'string' ? lastResponse.body : JSON.stringify(lastResponse.body || {});
    throw new Error(`GitHub PUT history file failed after retries: ${bodyText}`);
  }
}

return outputs;
